cssScope:
.sex-position-review-card {
  box-sizing: border-box;
  max-width: 560px;
  margin: 10px auto;
  padding: 18px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid #eee;
  box-shadow: 0 4px 16px rgba(0,0,0,.06);
  font-family: inherit;
  line-height: 1.6;
}
.sex-position-review-card .cr-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.sex-position-review-card .cr-title {
  font-size: 18px;
  font-weight: 700;
}
.sex-position-review-card .cr-score {
  font-size: 22px;
  font-weight: 700;
  white-space: nowrap;
}
.sex-position-review-card .cr-score span {
  font-size: 12px;
  font-weight: 400;
  opacity: .65;
}
.sex-position-review-card .cr-experience {
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 12px;
  background: #f7f7f7;
}
.sex-position-review-card .cr-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 0;
  font-size: 13px;
}
.sex-position-review-card .cr-row b {
  flex: 0 0 auto;
}
.sex-position-review-card .cr-row span {
  text-align: right;
  opacity: .85;
}
.sex-position-review-card .cr-section {
  margin-top: 14px;
}
.sex-position-review-card .cr-label {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 4px;
}
.sex-position-review-card .cr-text {
  font-size: 13px;
  opacity: .9;
}
.sex-position-review-card .cr-note {
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid #eee;
  font-size: 11px;
  opacity: .55;
}

